from pydantic import BaseModel, field_validator, model_validator

class RegistroEvento(BaseModel):
    nombre: str
    capacidad_minima: int
    capacidad_maxima: int

    @field_validator("nombre")
    @classmethod
    def nombre_no_vacio(cls, v: str) -> str:
        if not v.strip():
            raise ValueError("El nombre no puede consistir unicamente en espacios en blanco")
        return v.strip().title()

    @model_validator(mode="after")
    def verificar_capacidades(self) -> "RegistroEvento":
        if self.capacidad_minima > self.capacidad_maxima:
            raise ValueError("capacidad_minima no puede ser mayor que capacidad_maxima")
        return self

