from pydantic import BaseModel, field_validator

class Contacto(BaseModel):
    email: str

    @field_validator("email")
    @classmethod
    def validar_arroba(cls, v: str) -> str:
        if "@" not in v:
            raise ValueError("El email debe contener @")
        return v
